import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

// Story F3 — Button, checked in the source.
//
// The Button paints only through the redesign's tokens: no literal colors,
// none of the old color tokens and only the new pill radius. Its old
// variants (primary, quiet, danger) are gone from every call site, and the
// pill radius is a single token in @theme. The rendered look is
// checked in the browser by e2e/buttons.spec.ts.
// Do not edit this file to match an implementation.

const SRC = fileURLToPath(new URL('../../', import.meta.url));

function source(path: string) {
  return readFileSync(join(SRC, path), 'utf8');
}

function withoutComments(code: string) {
  return code.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');
}

function tsxFiles(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return tsxFiles(path);
    return name.endsWith('.tsx') ? [path] : [];
  });
}

const OLD_COLOR_TOKENS = [
  'background',
  'foreground',
  'ink-2',
  'ink-3',
  'rule',
  'rule-strong',
  'hover-tint',
  'panel-tint',
  'accent',
  'accent-hover',
  'ok-tint',
  'required',
  'recommended',
  'incomplete',
];

describe('F3 Button source', () => {
  it('uses no literal color, old color token, built-in palette color or old radius', () => {
    const code = withoutComments(source('components/ui/Button.tsx'));

    expect(code).not.toMatch(/#[0-9a-f]{3,8}\b/i);
    expect(code).not.toMatch(/\b(rgb|rgba|hsl|hsla|oklch)\(/);
    expect(code).not.toMatch(/\b(text|bg|border)-(white|black)\b/);
    expect(code).not.toMatch(/\brounded-btn\b/);
    expect(code).not.toMatch(/\brounded-\[/);
    expect(code).toMatch(/\brounded-pill\b/);
    expect(code).not.toMatch(/\bbrightness-/);
    for (const name of OLD_COLOR_TOKENS) {
      expect(code, name).not.toMatch(new RegExp(`(?:^|[\\s'"\`:])(?:text|bg|border)-${name}(?![\\w-])`));
    }
  });

  it('no call site passes an old variant', () => {
    const offenders: string[] = [];
    for (const file of tsxFiles(SRC)) {
      const code = withoutComments(readFileSync(file, 'utf8'));
      for (const tag of code.matchAll(/<Button\b[^>]*>/g)) {
        if (/\bvariant=["'{`]*(primary|quiet|danger)\b/.test(tag[0])) {
          offenders.push(`${file.slice(SRC.length)}: ${tag[0].replace(/\s+/g, ' ')}`);
        }
      }
    }
    expect(offenders).toEqual([]);
  });

  it('declares the pill radius once, inside @theme, as 9999px', () => {
    const css = source('app/globals.css').replace(/\/\*[\s\S]*?\*\//g, '');
    const inTheme: string[] = [];
    for (const match of css.matchAll(/@theme\b[^{]*\{/g)) {
      const start = match.index! + match[0].length;
      const body = css.slice(start, css.indexOf('}', start));
      for (const decl of body.matchAll(/(--radius-pill)\s*:\s*([^;]+);/g)) inTheme.push(decl[2].trim());
    }
    const everywhere = Array.from(css.matchAll(/--radius-pill\s*:/g));

    expect(inTheme).toEqual(['9999px']);
    expect(everywhere).toHaveLength(1);
  });
});
